mapper.select:
SELECT id, tenant_id AS tenantId, resource_key AS resourceKey, state_code AS stateCode, state_name AS stateName, description, sort_no AS sortNo, is_enabled AS enabled, metadata_json::text AS metadataJson FROM iam_resource_state WHERE deleted_at IS NULL AND ( #{tenantId} IS NULL OR tenant_id = #{tenantId} OR tenant_id = 0 )
AND resource_key = #{resourceKey}
AND is_enabled = #{enabled}
ORDER BY resource_key, tenant_id, sort_no, state_code

INSERT INTO iam_resource_state (
    tenant_id, resource_key, state_code, state_name, description, sort_no, is_enabled,
    metadata_json, created_by, updated_by
)
VALUES (
    #{tenantId}, #{resourceKey}, #{stateCode}, #{stateName}, #{description}, #{sortNo}, #{enabled},
    CAST(#{metadataJson} AS jsonb), #{operator}, #{operator}
)
RETURNING id

SELECT id, tenant_id AS tenantId, resource_key AS resourceKey, action_code AS actionCode, action_name AS actionName, permission_code AS permissionCode, description, sort_no AS sortNo, is_enabled AS enabled, metadata_json::text AS metadataJson FROM iam_resource_action WHERE deleted_at IS NULL AND ( #{tenantId} IS NULL OR tenant_id = #{tenantId} OR tenant_id = 0 )
AND resource_key = #{resourceKey}
AND is_enabled = #{enabled}
ORDER BY resource_key, tenant_id, sort_no, action_code

INSERT INTO iam_resource_action (
    tenant_id, resource_key, action_code, action_name, permission_code, description, sort_no, is_enabled,
    metadata_json, created_by, updated_by
)
VALUES (
    #{tenantId}, #{resourceKey}, #{actionCode}, #{actionName}, #{permissionCode}, #{description}, #{sortNo}, #{enabled},
    CAST(#{metadataJson} AS jsonb), #{operator}, #{operator}
)
RETURNING id

