INSERT INTO iam_role_state_action_rule (
    tenant_id, role_id, resource_key, state_code, action_code, is_enabled, created_by, updated_by
)
VALUES (
    #{tenantId}, #{roleId}, #{resourceKey}, #{stateCode}, #{actionCode}, true, #{operator}, #{operator}
)

mapper.select:
SELECT DISTINCT CONCAT(rule.resource_key, ':', rule.state_code) AS ruleKey, rule.action_code AS actionCode FROM iam_role_state_action_rule rule JOIN iam_resource_state state ON state.resource_key = rule.resource_key AND state.state_code = rule.state_code AND state.tenant_id IN (rule.tenant_id, 0) AND state.deleted_at IS NULL AND state.is_enabled = true JOIN iam_resource_action action ON action.resource_key = rule.resource_key AND action.action_code = rule.action_code AND action.tenant_id IN (rule.tenant_id, 0) AND action.deleted_at IS NULL AND action.is_enabled = true WHERE rule.tenant_id = #{tenantId} AND rule.role_id IN
#{roleId}
AND rule.deleted_at IS NULL AND rule.is_enabled = true ORDER BY ruleKey, actionCode
